I ran your exact question against the available expression-validator and security-prompt tooling. Results first, because they shape the recommendations:

| Probe | Result | Takeaway |
|---|---|---|
| `(a * b) + sqrt(c) / 2` | ✅ valid | Normal arithmetic + whitelisted function calls pass |
| `__import__('os').system('rm -rf /')` | ⛔ rejected — `Unexpected character '_'` | The grammar has **no identifiers**, so Python-level escape hatches die at the lexer |
| `1 + 2; import os` | ⛔ rejected — `Expected semicolon or newline after statement` | Statement chaining blocked |
| `(lambda: 1)()` | ⛔ rejected | Lambdas blocked |
| `((((((((((1+2))))))))))` with `max_depth=5` | ⚠️ **returned "valid"** | **Depth limiting on parentheses is not enforced by that check** — you must cap depth yourself |
| `2 ** 10` | ⛔ rejected in this grammar | `**` isn't supported; the target grammar must be *your* choice, not an accident |
| `principal * 1.05 * 1.05 + 3` (with `principal=10000`) | ✅ `11028` | Variable binding works and resolves only from a supplied scope |
| `batch_evaluate` | ❌ tool handler error | Not every tool in a toolbox works — validate your pipeline's failure paths |

That last row is the real lesson: **a security control you haven't tested failing closed is not a control.**

---

## 1. The core principle

`eval()` with `{"__builtins__": {}}` is **not** a sandbox. This classic escape still works:

```python
.__class__.__mro__[1].__subclasses__()   # → reach os, subprocess, everything
```

So the rule is: **never hand a string to `eval`/`exec`/`compile`/`subprocess` shell.** Instead:

> **Lex → Parse to AST → Whitelist-walk the AST → Interpret the AST yourself with `Decimal`.**
> Anything not on the allowlist is a hard error, not a sanitization.

This maps directly to **OWASP A03:2021 – Injection** (the same class as SQLi/command injection) and **A04:2021 – Insecure Design** (missing resource bounds).

---

## 2. Reference implementation (drop-in)

```python
# calc/safe_eval.py
import ast
import logging
from decimal import Decimal, InvalidOperation, localcontext, ROUND_HALF_EVEN

log = logging.getLogger("calc.security")

MAX_LEN        = 256          # characters
MAX_NODES      = 200          # AST nodes  -> bounds complexity
MAX_DEPTH      = 20           # nesting    -> bounds recursion/DoS
MAX_ABS_VALUE  = Decimal("1e15")
MAX_EXPONENT   = Decimal("64")   # blocks 9**9**9 memory bombs

class ExpressionError(ValueError):
    """Raised for anything unsafe or unparseable. Never leaks internals."""

def _depth(node, d=0):
    if d > MAX_DEPTH:
        raise ExpressionError("expression too deeply nested")
    for child in ast.iter_child_nodes(node):
        _depth(child, d + 1)
    return d

_BIN_OPS = {ast.Add: "+", ast.Sub: "-", ast.Mult: "*", ast.Div: "/",
            ast.FloorDiv: "//", ast.Mod: "%", ast.Pow: "**"}
_UNARY_OPS = {ast.UAdd: "+", ast.USub: "-"}

def _sqrt(a: Decimal) -> Decimal:
    if a < 0:
        raise ExpressionError("square root of negative number")
    return a.sqrt()

def _round(a: Decimal, n: Decimal) -> Decimal:
    places = int(n)
    if not -12 <= places <= 12:
        raise ExpressionError("rounding precision out of range")
    return a.quantize(Decimal(1).scaleb(-places), rounding=ROUND_HALF_EVEN)

# name -> (min_args, max_args, fn)
FUNCS = {
    "abs":   (1, 1, abs),
    "sqrt":  (1, 1, _sqrt),
    "round": (2, 2, _round),
    "min":   (2, 8, min),
    "max":   (2, 8, max),
}

_ALLOWED_NODES = (
    ast.Expression, ast.BinOp, ast.UnaryOp, ast.Constant,
    ast.Name, ast.Load, ast.Call,
    *[_BIN_OPS], *_UNARY_OPS,
)

def parse(expr: str, allow_variables: bool = False) -> ast.Expression:
    if not isinstance(expr, str):
        raise ExpressionError("expression must be a string")
    if len(expr) > MAX_LEN:
        raise ExpressionError("expression too long")
    try:
        tree = ast.parse(expr, mode="eval")     # mode="eval" forbids statements
    except SyntaxError:
        raise ExpressionError("invalid syntax") from None

    nodes = list(ast.walk(tree))
    if len(nodes) > MAX_NODES:
        raise ExpressionError("expression too complex")
    _depth(tree)

    for node in nodes:
        if isinstance(node, ast.Name) and not allow_variables:
            raise ExpressionError("variables are not allowed here")
        if not isinstance(node, _ALLOWED_NODES):
            raise ExpressionError(f"disallowed construct: {type(node).__name__}")
        if isinstance(node, ast.Constant) and not isinstance(node.value, (int, float)):
            raise ExpressionError("only numeric literals are allowed")
    return tree

def _eval(node: ast.AST, scope: dict[str, Decimal]) -> Decimal:
    if isinstance(node, ast.Expression):
        return _eval(node.body, scope)

    if isinstance(node, ast.Constant):
        try:
            return Decimal(str(node.value))
        except InvalidOperation:
            raise ExpressionError("invalid number") from None

    if isinstance(node, ast.Name):
        if node.id not in scope:
            raise ExpressionError("unknown variable")
        return scope[node.id]

    if isinstance(node, ast.UnaryOp):
        if type(node.op) not in _UNARY_OPS:
            raise ExpressionError("unsupported unary operator")
        v = _eval(node.operand, scope)
        return +v if isinstance(node.op, ast.UAdd) else -v

    if isinstance(node, ast.BinOp):
        op = _BIN_OPS.get(type(node.op))
        if op is None:
            raise ExpressionError("unsupported operator")
        a, b = _eval(node.left, scope), _eval(node.right, scope)
        try:
            if op == "+":  return a + b
            if op == "-":  return a - b
            if op == "*":  return a * b
            if op == "/":
                if b == 0: raise ExpressionError("division by zero")
                return a / b
            if op == "//":
                if b == 0: raise ExpressionError("division by zero")
                return (a / b).to_integral_value(rounding="ROUND_FLOOR")
            if op == "%":
                if b == 0: raise ExpressionError("division by zero")
                return a % b
            if op == "**":
                if b != b.to_integral_value() or abs(b) > MAX_EXPONENT:
                    raise ExpressionError("exponent out of range")
                return a ** int(b)
        except InvalidOperation:
            raise ExpressionError("arithmetic error") from None
        raise ExpressionError("unsupported operator")

    if isinstance(node, ast.Call):
        if not isinstance(node.func, ast.Name):        # blocks a.b(), a[0]()
            raise ExpressionError("disallowed call target")
        spec = FUNCS.get(node.func.id)
        if spec is None:
            raise ExpressionError("function not allowed")
        lo, hi, fn = spec
        if not lo <= len(node.args) <= hi or node.keywords:
            raise ExpressionError("bad argument count")
        return fn(*[_eval(a, scope) for a in node.args])

    raise ExpressionError("disallowed expression")

def evaluate(expr: str, variables: dict | None = None) -> str:
    scope = {k: Decimal(str(v)) for k, v in (variables or {}).items()}
    if set(scope) - {"principal", "rate", "years", "x", "y", "z"}:
        raise ExpressionError("variable not permitted")
    tree = parse(expr, allow_variables=bool(scope))
    with localcontext() as ctx:
        ctx.prec = 28
        result = _eval(tree, scope)
        ctx.prec = 28
    if abs(result) > MAX_ABS_VALUE:
        raise ExpressionError("result out of range")
    return format(result.normalize(), "f")
```

### FastAPI wiring

```python
from fastapi import APIRouter, HTTPException, Request
from pydantic import BaseModel, Field, field_validator

router = APIRouter()

class CalcIn(BaseModel):
    expression: str = Field(min_length=1, max_length=256)
    variables: dict[str, float] = Field(default_factory=dict)

    @field_validator("expression")
    @classmethod
    def no_control_chars(cls, v: str) -> str:
        if any(ord(c) < 32 for c in v):
            raise ValueError("control characters not allowed")
        return v

@router.post("/calc")
def calc(payload: CalcIn, request: Request):
    try:
        return {"result": evaluate(payload.expression, payload.variables)}
    except ExpressionError:
        # Security log: structured, truncated, never the full payload
        log.warning("calc_rejected", extra={
            "client": request.client.host if request.client else None,
            "expr_prefix": payload.expression[:64],
            "reason_code": "INVALID_EXPRESSION",
        })
        raise HTTPException(status_code=422, detail="Invalid expression") from None
```

Note the **generic error message** — `detail` never contains an AST, type name, or traceback (OWASP A05: misconfiguration, information exposure).

